function person(s,x,y,kind='villager',options={}){const frame=actorFrame(s);ellipse(x,y,frame.w*.29,frame.h*.075,'#293d3038');actor(s,options.key||kind+':'+Math.round(x)+':'+Math.round(y),x,y+2,'person-'+kind,frame.w,frame.h,options);}
function recoveryScenery(s,time){if(s.map==='river'){house(5*48,2*48,3*48,2*48,'#71836b');mechanismLabel('月溪藥屋',6.5*48,2*48+15);}if(s.map==='skyroad'){const open=R.worldRecoveryStatus(s).water;for(let y=10;y<12;y++)for(let x=10;x<12;x++){if(open){c.fillStyle='#7caaa088';c.fillRect(x*48,y*48,48,48);c.strokeStyle='#d6e5c277';c.lineWidth=2;c.beginPath();c.moveTo(x*48+7,y*48+28);c.lineTo(x*48+39,y*48+24+Math.sin(time*2+x+y)*3);c.stroke();c.fillStyle='#c3b991';c.fillRect(x*48+14,y*48+14,22,16);}else poly([[x*48+3,y*48+43],[x*48+6,y*48+6],[x*48+25,y*48-5],[x*48+46,y*48+16],[x*48+40,y*48+46]],'#969f83','#5f765d');}}if(s.map==='harbor'&&R.worldRecoveryStatus(s).ferry){c.fillStyle='#97afa344';c.fillRect(15*48,12*48,3*48,2*48);for(let i=0;i<4;i++){c.fillStyle='#ab946a';c.fillRect(15*48,12*48+i*22,3*48,15);}}if(s.map==='bastion'&&R.worldRecoveryStatus(s).granary){const x=16*48+24,y=13*48+24;c.strokeStyle='#7a7154';c.lineWidth=4;c.beginPath();c.moveTo(x-43,y+9);c.lineTo(x-43,y-72);c.lineTo(x+43,y-72);c.lineTo(x+43,y+9);c.stroke();poly([[x-53,y-69],[x,y-101],[x+53,y-69]],'#779276','#48674e');ellipse(x+29,y-15,15,9,'#666e55');ellipse(x+29,y-35-Math.sin(time*2)*4,5,10,'#e8e7c76a');}}
function recoveryObject(s,o,time){const {x,y,type}=o;if(type==='recovery-person'){person(s,x,y,R.friendlyAppearance(s,o),{key:'object:'+o.id});}else if(type==='recovery-cache'){image(o.data.spent?'openchest':'chest',x,y,42,40);}else if(type==='recovery-hoist'){c.strokeStyle='#7e7555';c.lineWidth=5;c.beginPath();c.moveTo(x-22,y+3);c.lineTo(x-22,y-112);c.lineTo(x+62,y-112);c.stroke();c.lineWidth=2;c.beginPath();c.moveTo(x+40,y-112);c.lineTo(x+40,y-(o.data.lowered?10:66));c.stroke();if(!o.data.spent){const by=y-(o.data.lowered?0:60);cargoBox(x+40,by,'#a6af8d',.65);ellipse(x+40,by-19,5,5,'#e2d292');}}else if(type==='recovery-tracks'){const lit=R.worldRecoveryStatus(s).tracks;for(let i=0;i<4;i++)ellipse(x-9+i*6,y-8-i*12,3,6,lit?'#e9d995':'#79928077');}else if(type==='recovery-channel'){if(o.data.open){ellipse(x,y-8,24,11,'#9bc2b4');c.strokeStyle='#dbe8c6';c.lineWidth=2;c.beginPath();c.arc(x,y-8,13+Math.sin(time*2)*3,0,Math.PI*2);c.stroke();}else poly([[x-24,y],[x-28,y-27],[x-9,y-46],[x+20,y-32],[x+26,y-2]],'#a1ac8c','#5e765a');}else{c.fillStyle='#c4bd96';c.fillRect(x-19,y-30,38,31);c.strokeStyle='#728166';c.lineWidth=2;c.strokeRect(x-19,y-30,38,31);}mechanismLabel(o.name,x,y+21);}
function mechanismLabel(text,x,y){c.font='bold 10px sans-serif';c.textAlign='center';c.fillStyle='#fff0c9';c.strokeStyle='#344d3d';c.lineWidth=3;c.strokeText(text,x,y);c.fillText(text,x,y);}
function mechanismScenery(s,time){if(s.map==='ashland-2'){const st=R.guardianStatus(s);c.fillStyle='#674e40';c.fillRect(8*48,4*48,6*48,5*48);for(let y=4;y<=8;y++)for(let x=8;x<=13;x++){ellipse(x*48+16,y*48+22,8+Math.sin(time*3+x+y)*2,4,'#d7a26366');}for(const [x,y]of R.GUARDIAN_TRACK){c.fillStyle='#a19c7e';c.fillRect(x*48+5,y*48+7,38,34);c.strokeStyle='#6c775f';c.strokeRect(x*48+5,y*48+7,38,34);}const px=13*48+24,py=5*48+24;ellipse(px,py,19,13,st.parked?'#e4d99b':'#718775');mechanismLabel('踏板',px,py-25);for(let y=1;y<15;y++){c.fillStyle=st.parked&&y===10?'#bfb28b':'#725e4e';c.fillRect(14*48,y*48,48,48);if(st.parked&&y===10){c.strokeStyle='#ead6a3';c.lineWidth=3;c.strokeRect(14*48+2,y*48+3,44,42);}else{ellipse(14*48+23,y*48+25,12+Math.sin(time*2+y)*2,5,'#d6a36b55');}}const rx=(st.rock[0]+.5)*48+(st.next.rock[0]-st.rock[0])*48*st.progress,ry=(st.rock[1]+.5)*48+(st.next.rock[1]-st.rock[1])*48*st.progress;poly([[rx-17,ry+10],[rx-22,ry-15],[rx-5,ry-32],[rx+17,ry-23],[rx+21,ry+7]],'#a5ab91','#586c58');mechanismLabel('沿南側窄道繞行',10*48,10*48+28);mechanismLabel(st.parked?'石橋已升起':'斷橋',14*48+24,10*48-8);}if(s.map==='sanctuary-1'){const st=R.plateStatus(s),x=17*48+24,y=8*48+24;ellipse(x,y+7,76,70,'#30473833');for(let i=0;i<3;i++){const radius=70-i*21;ellipse(x,y,radius,radius,['#aaa98b','#c0b695','#d3c39b'][i]);c.strokeStyle=st.ready||st.done?'#f3dfa1':'#5f7965';c.lineWidth=3;c.beginPath();c.arc(x,y,radius-3,0,Math.PI*2);c.stroke();c.font='bold 13px serif';c.fillStyle='#344f3b';c.textAlign='center';c.fillText(R.PLATE_SYMBOLS[st.rings[i]],x,y-radius+17);}c.fillStyle=st.ready||st.done?'#f6e5ac':'#63846f';ellipse(x,y+9,9,9,c.fillStyle);}}
function mechanismObject(s,o,time){const {x,y,type,id}=o;if(type==='mechanism-statue'){ellipse(x,y+4,22,7,'#293f3344');poly([[x-17,y],[x-20,y-31],[x-12,y-45],[x+12,y-45],[x+20,y-31],[x+17,y]],'#a5ad91','#536f58');c.fillStyle='#b9bea0';c.fillRect(x-13,y-64,26,24);c.strokeStyle='#58725c';c.lineWidth=2;c.strokeRect(x-13,y-64,26,24);c.fillStyle='#eddfa1';c.fillRect(x-8,y-56,5,4);c.fillRect(x+3,y-56,5,4);const a=o.data.dir*Math.PI/2;c.strokeStyle='#f2d896';c.lineWidth=3;c.beginPath();c.moveTo(x,y-23);c.lineTo(x+Math.cos(a)*17,y-23+Math.sin(a)*17);c.stroke();mechanismLabel(o.data.parked?'守住踏板':'守路石像',x,y+20);return;}if(type==='mechanism-altar')return;if(type==='mechanism-seal'){poly([[x,y-39],[x+15,y-22],[x,y-5],[x-15,y-22]],'#d9cd98','#71866b');c.fillStyle='#456149';c.textAlign='center';c.font='bold 14px serif';c.fillText({sun:'日',moon:'月',star:'星'}[o.data.seal],x,y-17);}else if(type==='mechanism-ring'){ellipse(x,y,20,7,'#3e584044');c.strokeStyle='#bfc095';c.lineWidth=6;c.beginPath();c.arc(x,y-19,15,0,Math.PI*2);c.stroke();c.fillStyle='#647b62';c.fillRect(x-4,y-20,8,22);}else if(type==='mechanism-lore'){c.fillStyle='#9fab8a';c.fillRect(x-19,y-48,38,48);c.strokeStyle='#d6d09e';c.lineWidth=2;for(let i=0;i<3;i++){c.beginPath();c.moveTo(x-10,y-35+i*10);c.lineTo(x+10,y-35+i*10);c.stroke();}if(R.plateStatus(s).lore)ellipse(x,y-54,7+Math.sin(time*3),4,'#f3df9b');}else if(type==='mechanism-console'){c.fillStyle='#9fa98b';c.fillRect(x-23,y-41,46,42);poly([[x-26,y-41],[x-17,y-55],[x+17,y-55],[x+26,y-41]],'#bfc19d','#64785e');mechanismLabel(R.guardianStatus(s).plan.length+' / 12',x,y-20);}else{c.fillStyle='#869b80';c.fillRect(x-15,y-20,30,21);c.strokeStyle='#d0c38e';c.lineWidth=5;c.beginPath();c.moveTo(x,y-19);c.lineTo(x+(id.includes('reset')?-12:12),y-41);c.stroke();}mechanismLabel(o.name,x,y+22);}
function cargoBox(x,y,color='#a88c63',size=1){c.save();c.translate(x,y);c.scale(size,size);ellipse(1,2,19,6,'#29432f33');c.fillStyle=color;c.fillRect(-16,-29,32,29);c.strokeStyle='#5e6448';c.lineWidth=2;c.strokeRect(-16,-29,32,29);c.beginPath();c.moveTo(-16,-25);c.lineTo(16,-3);c.moveTo(16,-25);c.lineTo(-16,-3);c.stroke();c.restore();}
