if(type==='grass'){for(let n=-2;n<=2;n++){c.strokeStyle=n%2?'#395f44':'#6a965d';c.lineWidth=5;c.beginPath();c.moveTo(x+n*7,y);c.lineTo(x+n*9+Math.sin(time+n)*2,y-22-Math.abs(n)*3);c.stroke();}return;}if(type==='explore'){const done=R.explorationGateDone?.(s);if(id==='secret-cache'||id==='explore-tool'){image((id==='secret-cache'?s.exploration?.treasures.includes(s.map):s.exploration?.tools.includes(o.data.tool))?'openchest':'chest',x,y,46,46);}else if(id.startsWith('secret-gate')){if(o.data.tool==='gauntlet'){poly([[x-27,y],[x-32,y-28],[x-12,y-51],[x+17,y-45],[x+29,y-18],[x+25,y]],done?'#adbba0':'#7b8e7e','#526750');}else if(o.data.tool==='lantern'){c.fillStyle='#7a8973';c.fillRect(x-23,y-48,46,49);ellipse(x,y-24,9,15,done?'#f5d682':'#354a3d');}else{c.strokeStyle=done?'#ddc68e':'#7d765d';c.lineWidth=6;c.beginPath();c.moveTo(x-24,y-16);c.lineTo(x+24,y-(done?16:39));c.stroke();}}else{c.fillStyle='#a4ad8e';c.fillRect(x-19,y-30,38,30);}c.fillStyle='#f9eac5';c.strokeStyle='#314c38';c.lineWidth=3;c.font='bold 11px sans-serif';c.textAlign='center';c.strokeText(o.name,x,y+17);c.fillText(o.name,x,y+17);return;}if(type==='npc'||type==='shop'||type==='campaign'&&['elder','captain','guide'].includes(id)||type==='campaign'&&id.startsWith('side-')){const kind=R.friendlyAppearance(s,o);person(s,x,y,kind,{key:'object:'+o.id});if(id==='elder'&&!s.flags.started){c.fillStyle='#f8df8d';c.font='bold 21px serif';c.textAlign='center';c.fillText('!',x,y-78+Math.sin(time*2)*3);}return;}
